package it.penny.api.workspace;

import it.penny.api.security.*;
import it.penny.api.common.AuditLog;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;

@RestController
@RequestMapping("/api/workspace")
public class WorkspaceController {
 private final JdbcTemplate db;private final PennyUserRepository users;private final RbacService rbac;private final AuditLog audit;
 public WorkspaceController(JdbcTemplate db,PennyUserRepository users,RbacService rbac,AuditLog audit){this.db=db;this.users=users;this.rbac=rbac;this.audit=audit;}
 private PennyUser require(Authentication a,String permission){var u=a==null?null:users.findByEmailIgnoreCase(a.getName()).orElse(null);rbac.require(u,permission);return u;}
 private static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Elemento non trovato");}
 private void customer(Long id,Authentication a,boolean required){if(id==null){if(required)throw bad("Cliente obbligatorio");return;}require(a,"CUSTOMERS_READ");if(db.queryForObject("SELECT count(*) FROM penny_customers WHERE id=? AND deleted_at IS NULL",Integer.class,id)!=1)throw bad("Cliente non valido");}
 private static void page(int page,int size){if(page<0||page>100000||size<1||size>100)throw bad("Paginazione non valida");}
 static String filename(String input){String value=input==null?"documento":input.replace('\\','/');value=value.substring(value.lastIndexOf('/')+1).replaceAll("[\\p{Cntrl}\\\";]","_").trim();if(value.isBlank())value="documento";return value.length()>200?value.substring(0,200):value;}
 static String safeMime(byte[] bytes){if(bytes.length==0||bytes.length>5242880)throw bad("Documento vuoto o superiore a 5 MB");if(bytes.length>=5&&new String(bytes,0,5,StandardCharsets.US_ASCII).equals("%PDF-"))return "application/pdf";if(bytes.length>=8&&bytes[0]==(byte)0x89&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G'&&bytes[4]==13&&bytes[5]==10&&bytes[6]==26&&bytes[7]==10)return "image/png";if(bytes.length>=3&&bytes[0]==(byte)0xff&&bytes[1]==(byte)0xd8&&bytes[2]==(byte)0xff)return "image/jpeg";return "application/octet-stream";}
 @GetMapping("/documents") public Map<String,Object> documents(@RequestParam(required=false) Long customerId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication a){require(a,"DOCUMENTS_READ");page(page,size);String where=" FROM penny_documents d JOIN penny_customers c ON c.id=d.customer_id WHERE d.deleted_at IS NULL AND (?::bigint IS NULL OR d.customer_id=?)";return Map.of("items",db.queryForList("SELECT d.id,d.customer_id AS \"customerId\",c.name AS \"customerName\",d.sale_order_id AS \"saleOrderId\",d.installed_product_id AS \"installedProductId\",d.catalog_product_id AS \"catalogProductId\",d.record_id AS \"recordId\",d.filename,d.mime_type AS \"mimeType\",octet_length(d.content) AS size,d.created_at AS \"createdAt\""+where+" ORDER BY d.id DESC LIMIT ? OFFSET ?",customerId,customerId,size,page*size),"total",Objects.requireNonNull(db.queryForObject("SELECT count(*)"+where,Long.class,customerId,customerId)),"page",page,"size",size);}
 @GetMapping("/documents/link-permissions") public Map<String,Object> linkPermissions(Authentication a){var u=require(a,"DOCUMENTS_WRITE");return Map.of("sales",rbac.allowed(u.id,"SALES_READ"),"products",rbac.allowed(u.id,"PRODUCTS_READ"),"catalog",rbac.allowed(u.id,"CATALOG_READ"),"records",List.of("TRAINING_READ","CONTRACTS_READ","ACTIVITIES_READ").stream().anyMatch(p->rbac.allowed(u.id,p)));}
 @GetMapping("/documents/record-options") public Map<String,Object> recordOptions(@RequestParam Long customerId,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication a){var u=require(a,"DOCUMENTS_WRITE");customer(customerId,a,true);page(page,size);if(q.length()>100)throw bad("Ricerca troppo lunga");var kinds=new ArrayList<String>();for(String kind:List.of("TRAINING","CONTRACT","DEVELOPMENT","TECHNICAL","COMMERCIAL"))if(rbac.allowed(u.id,it.penny.api.records.CustomerRecordService.permission(kind)+"_READ"))kinds.add(kind);if(kinds.isEmpty())return Map.of("items",List.of(),"total",0);var named=new org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate(db);var p=new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("customer",customerId).addValue("kinds",kinds).addValue("q","%"+q.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%").addValue("size",size).addValue("offset",page*size);String where=" FROM penny_customer_records WHERE customer_id=:customer AND kind IN (:kinds) AND deleted_at IS NULL AND lower(name) LIKE :q";return Map.of("items",named.queryForList("SELECT id,name,kind"+where+" ORDER BY name,id LIMIT :size OFFSET :offset",p),"total",Objects.requireNonNull(named.queryForObject("SELECT count(*)"+where,p,Long.class)));}
 @PostMapping("/documents") @Transactional public Map<String,Object> upload(@RequestParam Long customerId,@RequestParam(required=false) Long saleOrderId,@RequestParam(required=false) Long installedProductId,@RequestParam(required=false) Long catalogProductId,@RequestParam(required=false) Long recordId,@RequestParam MultipartFile file,Authentication a) throws java.io.IOException {
  var user=require(a,"DOCUMENTS_WRITE");customer(customerId,a,true);if(saleOrderId!=null){require(a,"SALES_READ");if(db.queryForObject("SELECT count(*) FROM penny_sales_orders WHERE id=? AND customer_id=?",Integer.class,saleOrderId,customerId)!=1)throw bad("Ordine di un altro cliente o inesistente");}
  if(installedProductId!=null){require(a,"PRODUCTS_READ");if(db.queryForObject("SELECT count(*) FROM penny_installed_products WHERE id=? AND customer_id=? AND deleted_at IS NULL",Integer.class,installedProductId,customerId)!=1)throw bad("Prodotto installato di un altro cliente o inesistente");}
  if(catalogProductId!=null){require(a,"CATALOG_READ");if(db.queryForObject("SELECT count(*) FROM penny_catalog_products WHERE id=? AND deleted_at IS NULL",Integer.class,catalogProductId)!=1)throw bad("Prodotto catalogo inesistente");}
  if(recordId!=null){var records=db.queryForList("SELECT kind FROM penny_customer_records WHERE id=? AND customer_id=? AND deleted_at IS NULL",recordId,customerId);if(records.isEmpty())throw bad("Scheda di un altro cliente o inesistente");require(a,it.penny.api.records.CustomerRecordService.permission(records.getFirst().get("kind").toString())+"_READ");}
  if(file==null||file.getSize()>5242880)throw bad("Documento massimo 5 MB");byte[] bytes=file.getBytes();String mime=safeMime(bytes),name=filename(file.getOriginalFilename());long id=Objects.requireNonNull(db.queryForObject("INSERT INTO penny_documents(customer_id,sale_order_id,filename,mime_type,content,uploaded_by,installed_product_id,catalog_product_id,record_id) VALUES (?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,customerId,saleOrderId,name,mime,bytes,user.id,installedProductId,catalogProductId,recordId));audit.record(a,"DOCUMENT_UPLOADED","DOCUMENT",id,Map.of("customerId",customerId,"bytes",bytes.length));return Map.of("id",id);
 }
 @GetMapping("/documents/{id}/download") public ResponseEntity<byte[]> download(@PathVariable long id,Authentication a){require(a,"DOCUMENTS_READ");var rows=db.queryForList("SELECT filename,mime_type,content FROM penny_documents WHERE id=? AND deleted_at IS NULL",id);if(rows.isEmpty())throw missing();var row=rows.getFirst();return ResponseEntity.ok().contentType(MediaType.parseMediaType((String)row.get("mime_type"))).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename((String)row.get("filename"),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").header(HttpHeaders.CACHE_CONTROL,"no-store").body((byte[])row.get("content"));}
 @DeleteMapping("/documents/{id}") @Transactional public Map<String,Object> deleteDocument(@PathVariable long id,Authentication a){require(a,"DOCUMENTS_WRITE");if(db.update("UPDATE penny_documents SET deleted_at=now() WHERE id=? AND deleted_at IS NULL",id)!=1)throw missing();audit.record(a,"DOCUMENT_DELETED","DOCUMENT",id,Map.of());return Map.of("deleted",true);}
 @PostMapping("/documents/{id}/restore") @Transactional public Map<String,Object> restoreDocument(@PathVariable long id,Authentication a){require(a,"DOCUMENTS_WRITE");if(db.update("UPDATE penny_documents SET deleted_at=NULL WHERE id=? AND deleted_at>=now()-interval '30 days'",id)!=1)throw missing();audit.record(a,"DOCUMENT_RESTORED","DOCUMENT",id,Map.of());return Map.of("restored",true);}
 public record Reminder(Long customerId,String message,LocalDate dueOn){}
 @GetMapping("/notifications") public Map<String,Object> notifications(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication a){var user=require(a,"NOTIFICATIONS_READ");page(page,size);return Map.of("items",db.queryForList("SELECT id,customer_id AS \"customerId\",message,due_on AS \"dueOn\",status,created_at AS \"createdAt\" FROM penny_notifications WHERE user_id=? ORDER BY CASE WHEN status='UNREAD' THEN 0 ELSE 1 END,due_on,id DESC LIMIT ? OFFSET ?",user.id,size,page*size),"total",Objects.requireNonNull(db.queryForObject("SELECT count(*) FROM penny_notifications WHERE user_id=?",Long.class,user.id)),"page",page,"size",size);}
 @PostMapping("/notifications") @Transactional public Map<String,Object> createReminder(@RequestBody Reminder input,Authentication a){var user=require(a,"NOTIFICATIONS_WRITE");if(input==null||input.dueOn()==null||input.message()==null||input.message().isBlank()||input.message().length()>2000)throw bad("Messaggio e data obbligatori (massimo 2000 caratteri)");customer(input.customerId(),a,false);long id=Objects.requireNonNull(db.queryForObject("INSERT INTO penny_notifications(user_id,customer_id,message,due_on) VALUES (?,?,?,?) RETURNING id",Long.class,user.id,input.customerId(),input.message().trim(),input.dueOn()));audit.record(a,"REMINDER_CREATED","NOTIFICATION",id,Map.of());return Map.of("id",id);}
 public record State(String status){}
 @PutMapping("/notifications/{id}") @Transactional public Map<String,Object> updateReminder(@PathVariable long id,@RequestBody State input,Authentication a){var user=require(a,"NOTIFICATIONS_WRITE");if(input==null||!Set.of("READ","CANCELLED").contains(Objects.toString(input.status(),"")))throw bad("Stato non valido");if(db.update("UPDATE penny_notifications SET status=?,updated_at=now() WHERE id=? AND user_id=? AND status<>'CANCELLED'",input.status(),id,user.id)!=1)throw missing();audit.record(a,"REMINDER_"+input.status(),"NOTIFICATION",id,Map.of());return Map.of("updated",true);}
 @GetMapping("/notifications/due-alerts") public Map<String,Object> alerts(Authentication a){var user=require(a,"NOTIFICATIONS_READ");var result=new ArrayList<Map<String,Object>>();if(rbac.allowed(user.id,"PRODUCTS_READ"))result.addAll(db.queryForList("SELECT id AS \"resourceId\",name AS message,license_expires_on AS \"dueOn\",'SOFTWARE' AS kind FROM penny_installed_products WHERE deleted_at IS NULL AND status<>'RETIRED' AND license_expires_on<=current_date+20 UNION ALL SELECT id,name,(business->>'expiresOn')::date,'HARDWARE' FROM penny_installed_products WHERE deleted_at IS NULL AND status<>'RETIRED' AND category='HARDWARE' AND nullif(business->>'expiresOn','')::date<=current_date+20 ORDER BY \"dueOn\" LIMIT 100"));for(String kind:List.of("TRAINING","CONTRACT","DEVELOPMENT")){String permission=it.penny.api.records.CustomerRecordService.permission(kind)+"_READ";if(rbac.allowed(user.id,permission))result.addAll(db.queryForList("SELECT id AS \"resourceId\",name AS message,expires_on AS \"dueOn\",kind FROM penny_customer_records WHERE deleted_at IS NULL AND status<>'CANCELLED' AND kind=? AND expires_on<=current_date+20 ORDER BY expires_on LIMIT 100",kind));}return Map.of("items",result);}
}
